CREATE OR REPLACE FUNCTION public.has_tenant_permission(p_tenant_id uuid,p_permission_key text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (EXISTS(SELECT 1 FROM public.clinic_users cu JOIN public.role_permissions rp ON rp.role_id=cu.role_id JOIN public.permissions p ON p.id=rp.permission_id WHERE cu.auth_user_id=auth.uid() AND cu.tenant_id=p_tenant_id AND cu.is_active AND p.permission_key=p_permission_key) OR EXISTS(SELECT 1 FROM public.clinic_user_permissions up JOIN public.permissions p ON p.id=up.permission_id JOIN public.clinic_users cu ON cu.id=up.user_id WHERE cu.auth_user_id=auth.uid() AND up.tenant_id=p_tenant_id AND up.granted AND cu.is_active AND p.permission_key=p_permission_key) OR EXISTS(SELECT 1 FROM public.clinic_user_permission_overrides ov JOIN public.permissions p ON p.id=ov.permission_id JOIN public.clinic_users cu ON cu.id=ov.user_id WHERE cu.auth_user_id=auth.uid() AND ov.tenant_id=p_tenant_id AND ov.granted AND cu.is_active AND p.permission_key=p_permission_key)) AND NOT EXISTS(SELECT 1 FROM public.clinic_user_permission_overrides ov JOIN public.permissions p ON p.id=ov.permission_id JOIN public.clinic_users cu ON cu.id=ov.user_id WHERE cu.auth_user_id=auth.uid() AND ov.tenant_id=p_tenant_id AND NOT ov.granted AND cu.is_active AND p.permission_key=p_permission_key); $$;
